head.script:
// https://inswave01.atlassian.net/browse/WAEA-1379



// 테스트 설명, 유효성 값 설정
//  - 담당 범위 : 기본 동작 (미설정 시 GridView 값 적용 / onclick / ondblclick / onsecondclick)
//  - embeddedInput 무시, inputType checkbox/radio/button, viewType=icon 의 editModeEventIcon 적용과 viewTypeIconImage 예외는 _2 담당
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (설정 영역 con 옵션 미생성)
//  - hammerEnabled=true 터치 동작 문장은 제외 (gridView_P_editModeEvent_1 동일)
scwin.tData = {
    "description" : "[column > P > editModeEvent]<br/>Column 을 편집 모드로 변경하기 위한 마우스 이벤트 종류를 설정합니다.",
    "validation" : [
        "미설정 시, GridView 의 editModeEvent 속성값이 적용됩니다.",
        "onclick 설정 시, Cell 을 클릭하면 편집 모드로 변경됩니다.",
        "ondblclick 설정 시, Cell 을 더블 클릭하면 편집 모드로 변경됩니다.",
        "onsecondclick 설정 시, 첫 클릭으로 포커스가 이동되고 다시 클릭해야 편집 모드로 변경됩니다.",
        "onsecondclick 설정 시, 더블 클릭 시 편집 모드로 변경되지 않고 첫 클릭 후 시간을 두고 다시 클릭해야 합니다."
    ]
}



scwin.gVar = {
    // 편집 모드로 진입한 셀 ("rowIndex:columnID", 편집 종료 시 초기화)
    "editCell" : "",
    // 직전 조작 셀 / 시각 (같은 셀 다시 클릭 판정용)
    "lastCell" : "",
    "lastTime" : 0,
    // 조작 집계 (클릭 묶음 단위로 1회 출력)
    "pending" : null,
    "timer" : null
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    //  (GridView editModeEvent=onclick, Column editModeEvent 미설정)
    con_gridEditModeEvent.setValue("onclick");
    con_editModeEvent.setSelectedIndex(0);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 모든 Body Column (text / select / textarea / calendar / checkcombobox / autoComplete) 에 Column editModeEvent = con_editModeEvent 적용
//  - GridView editModeEvent = con_gridEditModeEvent
//  - 셀 클릭 묶음(클릭 / 더블 클릭 / 같은 셀 다시 클릭)마다 조작 후 포커스 셀과 편집 모드 진입 여부를 결과창에 자동 출력
scwin.comp_init = async function () {
    // 기존 타이머 / target / dataList / label 삭제
    if (scwin.gVar.timer) {
        clearTimeout(scwin.gVar.timer);
    }
    scwin.gVar.editCell = "";
    scwin.gVar.lastCell = "";
    scwin.gVar.lastTime = 0;
    scwin.gVar.pending = null;
    scwin.gVar.timer = null;
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] 두 옵션 선택 -> Target 재생성 -> 포커스가 없는 셀을 클릭 / 더블 클릭, 또는 클릭 후 1초 정도 뒤 같은 셀을 다시 클릭\n[확인] 조작마다 조작 종류, 조작 후 포커스 셀, 편집 모드 진입 여부가 결과창에 자동 출력"', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue, 미설정은 속성 자체를 넣지 않는다)
    let cGridEditModeEvent = con_gridEditModeEvent.getValue();
    let cEditModeEvent = con_editModeEvent.getValue();
    let attrEvent = (cEditModeEvent === '') ? '' : ' editModeEvent="' + cEditModeEvent + '"';

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="txt" name="txt" dataType="text"></w2:column>';
    strDlt += '<w2:column id="sel" name="sel" dataType="text"></w2:column>';
    strDlt += '<w2:column id="area" name="area" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cal" name="cal" dataType="date"></w2:column>';
    strDlt += '<w2:column id="ccb" name="ccb" dataType="text"></w2:column>';
    strDlt += '<w2:column id="auto" name="auto" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "txt" : "김철수", "sel" : "1", "area" : "서울시 강남구", "cal" : "20260105", "ccb" : "1", "auto" : "1" },
        { "txt" : "이영희", "sel" : "2", "area" : "부산시 해운대구", "cal" : "20260210", "ccb" : "2", "auto" : "2" },
        { "txt" : "박민준", "sel" : "3", "area" : "대구시 수성구", "cal" : "20260315", "ccb" : "3", "auto" : "3" }
    ], false);

    // 아이템 정의
    let strItems = '<w2:choices>';
    strItems += '<w2:item><w2:label>서울</w2:label><w2:value>1</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>부산</w2:label><w2:value>2</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대구</w2:label><w2:value>3</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" editModeEvent="' + cGridEditModeEvent + '" id="" style="width:860px;height:150px;"';
    strTarget += ' ev:onbeforeedit="scwin.target1_onbeforeedit" ev:oneditend="scwin.target1_oneditend">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="txt (text)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="sel (select)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column3" value="area (textarea)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="cal (calendar)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column5" value="ccb (checkcombobox)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column6" value="auto (autoComplete)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="txt" value=""' + attrEvent + '></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="select" id="sel" value=""' + attrEvent + '>' + strItems + '</w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="textarea" id="area" value=""' + attrEvent + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="calendar" dataType="date" calendarValueType="yearMonthDate" displayFormat="yyyy-MM-dd" id="cal" value=""' + attrEvent + '></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="checkcombobox" id="ccb" value=""' + attrEvent + '>' + strItems + '</w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="autoComplete" id="auto" value=""' + attrEvent + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 셀 클릭 감시 (capture 단계)
    if (scwin["target1"]) {
        target1.render.addEventListener("click", scwin.target1_clickCapture, true);
    }
}



// 편집 모드 진입 셀 기록
scwin.target1_onbeforeedit = function (rowIndex, colIndex, value) {
    scwin.gVar.editCell = rowIndex + ":" + target1.getColumnID(colIndex);
}



// 편집 종료 시 기록 초기화
scwin.target1_oneditend = function (rowIndex, colIndex, value) {
    scwin.gVar.editCell = "";
}



// 셀 클릭 묶음 집계
//  - Body 셀(td) 첫 클릭 시점에 조작 셀과 직전 조작 셀 / 경과 시간을 기록하고, 이어지는 클릭(편집창 위 클릭 포함)은 클릭 횟수(e.detail)만 갱신
//  - 마지막 클릭 400ms 후 1회 출력 (더블 클릭은 1회로 묶임)
scwin.target1_clickCapture = function (e) {
    let pending = scwin.gVar.pending;
    if (pending) {
        pending.detail = Math.max(pending.detail, e.detail);
    } else {
        let td = e.target.closest ? e.target.closest("td[id*='" + target1.id + "_cell_']") : null;
        let match = td ? td.id.match(/_cell_(\d+)_(\d+)$/) : null;
        if (!match) {
            return;
        }
        let rowIndex = Number(match[1]);
        let colId = target1.getColumnID(Number(match[2]));
        let cell = rowIndex + ":" + colId;
        let now = new Date().getTime();
        pending = {
            "rowIndex" : rowIndex,
            "colId" : colId,
            "detail" : e.detail,
            "again" : (scwin.gVar.lastCell === cell),
            "gap" : now - scwin.gVar.lastTime
        };
        scwin.gVar.pending = pending;
        scwin.gVar.lastCell = cell;
        scwin.gVar.lastTime = now;
    }
    if (scwin.gVar.timer) {
        clearTimeout(scwin.gVar.timer);
    }
    scwin.gVar.timer = setTimeout(scwin.reportClick, 400);
}



// 조작 종류 -> 조작 후 포커스 셀 / 편집 모드 진입 여부 출력
//  - validation 1 : Column 미설정 시 GridView editModeEvent 에 맞는 조작에서만 진입
//  - validation 2, 3 : 클릭 / 더블 클릭 시 진입 여부
//  - validation 4, 5 : 첫 클릭은 포커스만 이동, 더블 클릭은 미진입, 시간을 두고 다시 클릭하면 진입
scwin.reportClick = function () {
    let p = scwin.gVar.pending;
    scwin.gVar.pending = null;
    scwin.gVar.timer = null;
    if (!p) {
        return;
    }
    let action = "클릭";
    if (p.detail >= 2) {
        action = "더블 클릭";
    } else if (p.again) {
        action = "같은 셀 다시 클릭 (" + p.gap + "ms 후)";
    }
    let cell = p.rowIndex + ":" + p.colId;
    let edited = target1.isEditing() && scwin.gVar.editCell === cell;
    wf_body_bottom.getObj("scwin").setReturnValue(
        action + " : Row " + p.rowIndex + " / " + p.colId
        + " -> 포커스 셀 : Row " + target1.getFocusedRowIndex() + " / " + target1.getFocusedColumnID()
        + ", 편집 모드 " + (edited ? "진입" : "미진입"));
}
